import os
import re
import shutil
from collections.abc import Iterator
from pathlib import Path

# Keys are generated by the app (e.g. "gif/<32 hex>.gif"), never taken from user input; this is a second line of defence.
_KEY_RE = re.compile(r"^[a-z0-9][a-z0-9_./-]{0,200}$")


class LocalStorage:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _resolve(self, key: str) -> Path:
        if not _KEY_RE.match(key) or ".." in key or "//" in key:
            raise ValueError("invalid storage key")
        path = (self.root / key).resolve()
        if not path.is_relative_to(self.root):
            raise ValueError("invalid storage key")
        return path

    def put_file(self, key: str, src: Path) -> None:
        dest = self._resolve(key)
        dest.parent.mkdir(parents=True, exist_ok=True)
        part = dest.with_name(dest.name + ".part")
        shutil.copyfile(src, part)
        os.replace(part, dest)  # atomic: readers never see a half-written GIF

    def delete(self, key: str) -> None:
        try:
            self._resolve(key).unlink()
        except FileNotFoundError:
            pass

    def size(self, key: str) -> int | None:
        try:
            return self._resolve(key).stat().st_size
        except FileNotFoundError:
            return None

    def stream(self, key: str, chunk_size: int = 1024 * 256) -> Iterator[bytes]:
        with open(self._resolve(key), "rb") as f:
            while chunk := f.read(chunk_size):
                yield chunk

    def local_path(self, key: str) -> Path | None:
        p = self._resolve(key)
        return p if p.is_file() else None

    def public_redirect(self, key: str) -> str | None:
        return None
